function countHousePlacements(n) {
  const MOD = 1000000007;
  let empty = 1;
  let house = 1;

  for (let plot = 2; plot <= n; plot++) {
    const nextEmpty = (empty + house) % MOD;
    house = empty;
    empty = nextEmpty;
  }

  const side = (empty + house) % MOD;
  return Number((BigInt(side) * BigInt(side)) % BigInt(MOD));
}

