function countHousePlacements(n) {
  // Walk both sides together, one plot number at a time. State bit 0: house on the top plot;
  // bit 1: house on the bottom plot. Two consecutive states may not share a house on the same side.
  const MOD = 1000000007;
  let ways = [1, 0, 0, 0];
  for (let i = 0; i < n; i++) {
    const next = [0, 0, 0, 0];
    for (let prev = 0; prev < 4; prev++)
      for (let cur = 0; cur < 4; cur++)
        if ((prev & cur) === 0) next[cur] = (next[cur] + ways[prev]) % MOD;
    ways = next;
  }
  return ways.reduce((sum, w) => (sum + w) % MOD, 0);
}

